import{_ as e,o,c as r,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"Crimson/Seastar OSD Meeting 2018-12-11","description":"","frontmatter":{"title":"Crimson/Seastar OSD Meeting 2018-12-11","date":"2018-12-11T00:00:00.000Z","updated":"2018-12-20T00:00:00.000Z","tags":["Ceph","Distributed Storage","OSD","Crimson Messenger","ZooKeeper"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Crimson_Seastar_OSD_Meeting_2018-12-11.md","filePath":"posts/2018/Crimson_Seastar_OSD_Meeting_2018-12-11.md","lastUpdated":1780460162000}'),s={name:"posts/2018/Crimson_Seastar_OSD_Meeting_2018-12-11.md"};function l(n,i,a,p,g,_){return o(),r("div",null,[...i[0]||(i[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2018年12月11日</p><p><strong>参会人员</strong>： Michael、Divya、Riddick、Bobby等</p><p><strong>会议主题</strong>： Ceph分布式存储系统OSD服务模型、Promise调度器、Crimson消息传递框架及ZooKeeper集成讨论</p><p><strong>关键细节</strong>：</p><ul><li><strong>OSD服务模型</strong>： 讨论了OSD服务的模型设计，包括如何管理OSD和对象存储之间的关系，提出了创建一个新的OSD服务类。</li><li><strong>Promise调度器</strong>： 讨论了Promise调度器的修改，以确保磁盘操作的顺序。</li><li><strong>Crimson消息传递框架</strong>： 讨论了Crimson消息传递框架的集成和改进，包括日志记录、PID地址问题等。</li><li><strong>ZooKeeper集成</strong>： 讨论了ZooKeeper集成的工作进展，包括隐私保护和Crimson对象存储实现。</li></ul><p><strong>讨论的主要议题</strong>：</p><ul><li>如何设计OSD服务模型以更好地管理服务、对象存储和OSD之间的关系。</li><li>如何修改Promise调度器以确保操作的顺序。</li><li>如何集成和改进Crimson消息传递框架。</li><li>如何实现ZooKeeper集成，以提供更好的隐私保护和数据一致性。</li></ul><p><strong>决定的事项</strong>：</p><ul><li>创建一个新的OSD服务类，用于管理OSD和对象存储。</li><li>修改Promise调度器以确保操作的顺序。</li><li>集成和改进Crimson消息传递框架。</li><li>实现ZooKeeper集成。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Michael将负责设计OSD服务模型。</li><li>Divya将负责修改Promise调度器。</li><li>Riddick将负责集成和改进Crimson消息传递框架。</li><li>Bobby将负责实现ZooKeeper集成。</li><li>所有参与者将参与讨论和审查相关代码。</li></ul><p><strong>其他事项</strong>：</p><ul><li>会议还讨论了内存管理、缓存策略等技术问题。</li><li>会议结束后，所有参与者将分享他们的进展和遇到的问题。</li></ul><p><strong>关键词</strong>：</p><ul><li>OSD（对象存储守护进程）</li><li>Promise调度器</li><li>Crimson消息传递框架</li><li>ZooKeeper</li><li>Privacy</li><li>Performance</li><li>Reliability</li></ul>',16)])])}const d=e(s,[["render",l]]);export{S as __pageData,d as default};
